entries[35272] = { ["name"] = "Jenny's Whistle", ["text"] = "Quest Item\nUse: Call Fezzix Geartwists's faithful mule, Jenny. Can only be used while standing near a crashed flying machine in the Scalding Pools. (1 Min Cooldown)" }
entries[35273] = { ["name"] = "Study of Advanced Smelting", ["text"] = "Binds when picked up\nRequires Mining (375)\nUse: Teaches you how to make Hardened Khorium.\nAllows the miner to smelt khorium and hardened adamantite bars into a hardened khorium bar. Smelting hard khorium requires a forge.\nSell Price:\nHardened Khorium\nSell Price:\nRequires Khorium Bar (3), Hardened Adamantite Bar" }
